class LmdbLegacyFeedbackFailureRecoveryTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:legacy-failure:p1");
	private static final IRI P2 = VF.createIRI("urn:legacy-failure:p2");
	private static final String STEERING_PROPERTY = "rdf4j.optimizer.lmdb.leoRuleSteering";

	@Test
	void partiallyPublishedObservationIsNotExposedAfterCallbackFailure(
			@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		run(path, true);
	}

	@Test
	void completedObservationWithoutFailureStillLearns(@TempDir(cleanup = CleanupMode.NEVER) Path path)
			throws Exception {
		run(path, false);
	}

	private static void run(Path path, boolean fail) throws Exception {
		String previous = System.getProperty(STEERING_PROPERTY);
		System.setProperty(STEERING_PROPERTY, "true");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setBackgroundRawSamplingEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(path.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			statistics.bindExecutionSnapshot(OptionalLong.of(statistics.estimatorRuntime().snapshotVersion()));
			LmdbOperatorFeedbackStats provider = statistics.estimatorRuntime().feedback();
			FailingUnion observed = observed();
			observed.provider = provider;
			observed.fail = fail;
			if (fail) {
				assertThrows(IllegalStateException.class, () -> statistics.recordOperatorOutcome(observed));
				assertTrue(observed.failed.get(), "the callback failed after the operator cell was updated");
				assertNull(provider.estimate(union(), 600, 400, 10, 100),
						"an interrupted feedback publication cannot expose a partial sample");
			} else {
				statistics.recordOperatorOutcome(observed);
				assertNotNull(provider.estimate(union(), 600, 400, 10, 100),
						"a complete current observation remains learnable");
			}
		} finally {
			repository.shutDown();
			if (previous == null) {
				System.clearProperty(STEERING_PROPERTY);
			} else {
				System.setProperty(STEERING_PROPERTY, previous);
			}
		}
	}

	private static FailingUnion observed() {
		FailingUnion observed = union();
		Distinct root = new Distinct(observed);
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		observed.setCostFeedbackTrackingEnabled(true);
		observed.setCostFeedbackExpectedRows(10.0d);
		observed.setCostFeedbackExpectedWorkRows(100.0d);
		observed.setCostFeedbackReportQErrorThreshold(LmdbOperatorFeedbackStats.DEFAULT_REPORT_Q_ERROR_THRESHOLD);
		observed.setResultSizeEstimate(10.0d);
		observed.setCostEstimate(100.0d);
		observed.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, 100.0d);
		observed.setCostFeedbackActualRows(1_000L);
		observed.setCostFeedbackActualWorkRows(1_000.0d);
		observed.setCostFeedbackCloseCountActual(1L);
		observed.setCostFeedbackCompletedActual(true);
		observed.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
		return observed;
	}

	private static FailingUnion union() {
		FailingUnion result = new FailingUnion(sp("page", P1, "review"), sp("person", P2, "award"));
		PlanningGraphDomains.capture(result, PlanningGraphDomain.defaultGraph());
		return result;
	}

	private static StatementPattern sp(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("p", predicate, true, true), Var.of(object));
	}

	private static final class FailingUnion extends Union {
		private final AtomicBoolean failed = new AtomicBoolean();
		private LmdbOperatorFeedbackStats provider;
		private boolean fail;

		FailingUnion(StatementPattern left, StatementPattern right) {
			super(left, right);
		}

		@Override
		public String getStringMetricPlanned(String key) {
			if (fail && provider != null && Thread.holdsLock(provider)
					&& "optimizer.leoRuleSteeringApplied".equals(key)) {
				fail = false;
				failed.set(true);
				throw new IllegalStateException("injected callback failure after operator update");
			}
			return super.getStringMetricPlanned(key);
		}
	}
}
